export interface ProductSearchResult {
  product_id: string;
  base_product_id?: string | null;
  name?: string | null;
  brand?: string | null;
  ean?: string | null;
  price?: number | null;
  original_price?: number | null;
  quantity?: string | null;
  /** Unit of unit_price: kg, L or stuk. Null when no comparable unit exists, e.g. one price over several pack sizes */
  unit?: string | null;
  unit_price?: number | null;
  /** Product detail page URL */
  product_url?: string | null;
  image_url?: string | null;
  retailer: string;
  unified_category?: string | null;
  dietary_tags?: string[] | null;
  private_label?: boolean | null;
  is_promotional?: boolean;
  promotional_keywords?: string[] | null;
  promotion_status?: string | null;
  /** Promotion mechanism, one fixed vocabulary for every retailer: `percentage` (a price cut, incl. a plain was/now price), `multi_buy` ('2 voor 6,00', '3 stuks €5'), `one_plus_one` ('1+1 gratis', '2+1 gratis', '2e halve prijs'), `volume`, `limited` ('OP=OP'), `starting` ('vanaf'). Null when the retailer's label names no mechanism we can classify. */
  promotion_type?: string | null;
  /** The retailer's own id for the promotion this product takes part in, namespaced by retailer. Every product in the same promotion carries the same value, so `GET /api/v1/products?promo_group_id=...` lists them all. Scoped to the promotion week. Null when the retailer publishes no id. */
  promo_group_id?: string | null;
  /** True when the retailer states the products in this group combine toward one deal (e.g. 'Kies & Mix 2 voor 6,00'); false when it states the deal applies per product. Null when the retailer does not say: a shared `promo_group_id` alone does not prove the products can be mixed. */
  promo_group_mixable?: boolean | null;
  savings_percentage?: number | null;
  savings_amount?: number | null;
  multi_buy_quantity?: number | null;
  multi_buy_price?: number | null;
  valid_from?: string | null;
  valid_until?: string | null;
  valid_until_estimated?: boolean | null;
  in_store_only?: boolean | null;
  online_only?: boolean | null;
  loyalty_price?: number | null;
  loyalty_program?: string | null;
  max_per_customer?: number | null;
  extracted_at?: string | null;
  currency?: string;
  score: number;
}
